{
  "source_clauses": [
    {
      "id": "SRC-0001",
      "verbatim": "I need a compact folding stand for my desk.",
      "locator": "REQ-001"
    },
    {
      "id": "SRC-0002",
      "verbatim": "It should have three legs that fold in close to the body, so the whole thing becomes narrow and compact when I put it away.",
      "locator": "REQ-002"
    },
    {
      "id": "SRC-0003",
      "verbatim": "Everything should stay attached while it is folded.",
      "locator": "REQ-003"
    },
    {
      "id": "SRC-0004",
      "verbatim": "I do not want to take anything off to fold it, or loose pieces to look after.",
      "locator": "REQ-004"
    },
    {
      "id": "SRC-0005",
      "verbatim": "When I want to use it, I should be able to open it by hand, following a sequence that makes sense as I go.",
      "locator": "REQ-005"
    },
    {
      "id": "SRC-0006",
      "verbatim": "The three legs should end up spread apart in different directions so they give the stand a usable footprint on the desk.",
      "locator": "REQ-006"
    },
    {
      "id": "SRC-0007",
      "verbatim": "Nothing should come apart or fall off while I am opening it, and I should not need tools, a motor, or any other equipment to do it.",
      "locator": "REQ-007"
    },
    {
      "id": "SRC-0008",
      "verbatim": "Once it is open, it needs to stay open on its own.",
      "locator": "REQ-008"
    },
    {
      "id": "SRC-0009",
      "verbatim": "I should not have to hold the legs while I use it, and they should not be able to fold back, twist aside, or come off.",
      "locator": "REQ-009"
    },
    {
      "id": "SRC-0010",
      "verbatim": "Nothing should turn on its own, shift out of place, or move in some other direction I was not expecting.",
      "locator": "REQ-010"
    },
    {
      "id": "SRC-0011",
      "verbatim": "Before it can be folded again I want to have to do something deliberate, so it does not collapse just because I knocked it.",
      "locator": "REQ-011"
    },
    {
      "id": "SRC-0012",
      "verbatim": "After that deliberate release, it should fold back down to the same compact shape it started in.",
      "locator": "REQ-012"
    },
    {
      "id": "SRC-0013",
      "verbatim": "The opening and folding sequence should be repeatable, with all normal parts remaining attached and without anything needing to be removed and put back on.",
      "locator": "REQ-013"
    },
    {
      "id": "SRC-0014",
      "verbatim": "It is meant to hold a small object on my desk while I am working.",
      "locator": "REQ-014"
    },
    {
      "id": "SRC-0015",
      "verbatim": "It should also be something that can genuinely be built as a product and put together in a sensible order, and stay together through normal opening and folding.",
      "locator": "REQ-015"
    }
  ],
